import copy, math
import seqmodel

D,H,P,T = 4,2,3,3
def mk():
    b = seqmodel.TransformerBlock(D,H,P)
    b.attn.Wq = [[0.1*(2*a+j+1)-0.03 for j in range(D)] for a in range(D)]
    b.attn.Wk = [[-0.07+0.05*(a+j) for j in range(D)] for a in range(D)]
    b.attn.Wv = [[0.03*(a-j)+0.2 for j in range(D)] for a in range(D)]
    b.attn.Wo = [[0.04*(j-a)+0.1 for j in range(D)] for a in range(D)]
    b.W1 = [[0.02*(p+2*j)-0.05 for j in range(D)] for p in range(P)]
    b.b1 = [0.01*p-0.02 for p in range(P)]
    b.W2 = [[0.03*(j+p)-0.04 for p in range(P)] for j in range(D)]
    b.b2 = [0.02*j-0.05 for j in range(D)]
    return b
x0 = [[0.1,-0.2,0.3,0.05],[-0.15,0.25,-0.1,0.4],[0.05,0.05,-0.35,0.2]]
bias0 = [[0.1,0.0,-0.1],[0.05,-0.05,0.15]]
coef = [[0.7-0.13*(t*D+j) for j in range(D)] for t in range(T)]

def mutate(x, bias, b, delta, kind, i, j):
    if kind == "x":
        x[i][j] += delta
    elif kind == "b1":
        b.b1[i] += delta
    elif kind == "bias":
        bias[i][j] += delta

def numeric(kind, i, j, eps=1e-6):
    def L(delta):
        b = mk(); x = copy.deepcopy(x0); bias = copy.deepcopy(bias0)
        mutate(x, bias, b, delta, kind, i, j)
        y,_ = b.forward_relative(x, bias, None)
        return sum(coef[t][k]*y[t][k] for t in range(T) for k in range(D))
    return (L(eps)-L(-eps))/(2*eps)

b = mk()
b.forward_relative(copy.deepcopy(x0), copy.deepcopy(bias0), None)
dx,dWq,dWk,dWv,dWo,dW1,db1,dW2,db2,dbias = b.backward_relative(copy.deepcopy(coef))
bad = []
for t in range(T):
    for j in range(D):
        ng = numeric("x", t, j)
        if abs(ng-dx[t][j]) > 1e-6: bad.append(("dx",t,j,ng,dx[t][j]))
for p in range(P):
    ng = numeric("b1", p, 0)
    if abs(ng-db1[p]) > 1e-6: bad.append(("db1",p,ng,db1[p]))
for r in range(H):
    for q in range(3):
        ng = numeric("bias", r, q)
        if abs(ng-dbias[r][q]) > 1e-6: bad.append(("dbias",r,q,ng,dbias[r][q]))
print("mismatches:", bad)
